local Alignment={};Alignment.__index=Alignment
local function cp(v)if type(v)~="table"then return v end;local o={};for k,x in pairs(v)do o[cp(k)]=cp(x)end;return o end
local function id(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")~=nil end
local function num(v)return type(v)=="number"and v==v and v<math.huge and v>-math.huge end
local function pt(v)return type(v)=="table"and num(v.x)and num(v.y)and num(v.z)end
local function sub(a,b)return{x=a.x-b.x,y=a.y-b.y,z=a.z-b.z}end;local function dot(a,b)return a.x*b.x+a.y*b.y+a.z*b.z end
local function mul(a,n)return{x=a.x*n,y=a.y*n,z=a.z*n}end;local function add(a,b)return{x=a.x+b.x,y=a.y+b.y,z=a.z+b.z}end
local function cross(a,b)return{x=a.y*b.z-a.z*b.y,y=a.z*b.x-a.x*b.z,z=a.x*b.y-a.y*b.x}end
local function unit(v)local n=math.sqrt(dot(v,v));if n<0.000001 then return nil end;return mul(v,1/n)end
local function basis(p)local x=unit(sub(p.x,p.origin));if not x then return nil,"degenerate_frame"end;local z=unit(cross(x,sub(p.y,p.origin)));if not z then return nil,"collinear_frame"end;return{origin=cp(p.origin),x=x,y=unit(cross(z,x)),z=z}end
local function q(n)local s=n*1000000;return(s>=0 and math.floor(s+.5)or math.ceil(s-.5))/1000000 end
local function key(m,a)local out={m};for _,v in ipairs(a)do if type(v)=="table"then out[#out+1]=v.x..","..v.y..","..v.z else out[#out+1]=tostring(v)end end;return table.concat(out,"|")end
local function find(rows,p)for _,r in ipairs(rows)do if r.player_id==p then return r end end end
local function array(v)if type(v)~="table"then return false end;local n=0;for k in pairs(v)do if type(k)~="number"or k<1 or k%1~=0 then return false end;n=n+1 end;return n==#v end
local function session_ok(s)if type(s)~="table"or not id(s.player_id)or not id(s.entity_id)or type(s.revision)~="number"or s.revision<1 or s.revision%1~=0 or type(s.source)~="table"or type(s.target)~="table"then return false end;local order={{"source","origin"},{"source","x"},{"source","y"},{"target","origin"},{"target","x"},{"target","y"}};local missing=false;for _,p in ipairs(order)do local v=s[p[1]][p[2]];if v==nil then missing=true elseif missing or not pt(v)then return false end end;for _,f in ipairs({"source","target"})do for k in pairs(s[f])do if k~="origin"and k~="x"and k~="y"then return false end end;if s[f].y and not basis(s[f])then return false end end;return true end
local function request(self,rid,m,args)local k=key(m,args);for _,r in ipairs(self.request_rows)do if r.id==rid then if r.key~=k then return false,"request_conflict",{}end;return r.ok,r.code,cp(r.data)end end;return nil,k end
local function remember(self,rid,k,ok,code,data)self.request_rows[#self.request_rows+1]={id=rid,key=k,ok=ok,code=code,data=cp(data or{})};return ok,code,cp(data or{})end
function Alignment.new(o)o=o or{};if o.max_operations~=2 then return nil,"invalid_options"end;local s=setmetatable({session_rows={},request_rows={},spent_rows={},stopped=false,max_operations=2},Alignment);local st=o.state;if st~=nil then if type(st)~="table"or st.schema_version~=1 or not array(st.sessions)or not array(st.requests)or not array(st.spent)then return nil,"invalid_state"end;local seen_s,seen_r,seen_p={},{},{};for _,r in ipairs(st.sessions)do if not session_ok(r)or seen_s[r.player_id]then return nil,"invalid_state"end;seen_s[r.player_id]=true end;for _,r in ipairs(st.requests)do if type(r)~="table"or not id(r.id)or seen_r[r.id]or type(r.key)~="string"or r.key==""or type(r.ok)~="boolean"or type(r.code)~="string"or r.code==""or type(r.data)~="table"then return nil,"invalid_state"end;seen_r[r.id]=true end;for _,r in ipairs(st.spent)do if type(r)~="table"or not id(r.player_id)or seen_p[r.player_id]or type(r.count)~="number"or r.count%1~=0 or r.count<0 or r.count>2 then return nil,"invalid_state"end;seen_p[r.player_id]=true end;s.session_rows=cp(st.sessions);s.request_rows=cp(st.requests);s.spent_rows=cp(st.spent)end;return s end
local function spent(self,p)for _,r in ipairs(self.spent_rows)do if r.player_id==p then return r end end;local r={player_id=p,count=0};self.spent_rows[#self.spent_rows+1]=r;return r end
function Alignment:stage(rid,p,e,rev,f,slot,v)if self.stopped then return false,"shutdown",{}end;local args={p,e,rev,f,slot,v};local old,k,c=request(self,rid,"stage",args);if old~=nil then return old,k,c end;if not id(rid)or not id(p)or not id(e)or type(rev)~="number"or rev<1 or rev%1~=0 or(f~="source"and f~="target")or(slot~="origin"and slot~="x"and slot~="y")or not pt(v)then return false,"invalid_stage",{}end;local s=find(self.session_rows,p);if not s then s={player_id=p,entity_id=e,revision=rev,source={},target={}};self.session_rows[#self.session_rows+1]=s end;if s.entity_id~=e or s.revision~=rev then return remember(self,rid,k,false,"stage_identity_mismatch",{})end;local order={source={origin=1,x=2,y=3},target={origin=4,x=5,y=6}};local n=0;for _,a in ipairs({"source","target"})do for _,b in ipairs({"origin","x","y"})do if s[a][b]then n=n+1 end end end;if order[f][slot]~=n+1 then return remember(self,rid,k,false,"bad_stage_order",{})end;s[f][slot]=cp(v);if slot=="y"then local _,er=basis(s[f]);if er then s[f][slot]=nil;return remember(self,rid,k,false,er,{})end end;return remember(self,rid,k,true,"staged",{stage=n+1})end
function Alignment:solve(rid,p,e,rev,probe)if self.stopped then return false,"shutdown",{}end;local args={p,e,rev,probe};local old,k,c=request(self,rid,"solve",args);if old~=nil then return old,k,c end;if not id(rid)or not id(p)or not id(e)or type(rev)~="number"or rev<1 or rev%1~=0 or not pt(probe)then return false,"invalid_request",{}end;local s=find(self.session_rows,p);if not s or s.entity_id~=e or s.revision~=rev then return remember(self,rid,k,false,"incomplete_stage",{})end;local sf,se=basis(s.source);local tf,te=basis(s.target);if not sf or not tf then return remember(self,rid,k,false,se or te,{})end;local budget=spent(self,p);if budget.count>=2 then return remember(self,rid,k,false,"budget_exceeded",{})end;local d=sub(probe,sf.origin);local m=add(tf.origin,add(mul(tf.x,dot(d,sf.x)),add(mul(tf.y,dot(d,sf.y)),mul(tf.z,dot(d,sf.z)))));budget.count=budget.count+1;for i=#self.session_rows,1,-1 do if self.session_rows[i]==s then table.remove(self.session_rows,i)end end;local function qp(v)return{x=q(v.x),y=q(v.y),z=q(v.z)}end;return remember(self,rid,k,true,"solved",{position={x=q(m.x),y=q(m.y),z=q(m.z)},basis={x=qp(tf.x),y=qp(tf.y),z=qp(tf.z)}})end
function Alignment:clear(rid,p)if self.stopped then return false,"shutdown",{}end;if not id(rid)or not id(p)then return false,"invalid_request",{}end;local args={p};local old,k,c=request(self,rid,"clear",args);if old~=nil then return old,k,c end;for i=#self.session_rows,1,-1 do if self.session_rows[i].player_id==p then table.remove(self.session_rows,i)end end;return remember(self,rid,k,true,"cleared",{})end
function Alignment:snapshot()return cp({sessions=self.session_rows,spent=self.spent_rows})end
function Alignment:save()return{schema_version=1,sessions=cp(self.session_rows),requests=cp(self.request_rows),spent=cp(self.spent_rows)}end
function Alignment:shutdown()self.stopped=true;return true,"shutdown"end
return Alignment
